/**
 * Chat port: what the chat UI needs from the backend. Two implementations, same type:
 * `createHttpChatApi` (POST + SSE against the `langgraph-graph` endpoint) and `createFakeChatApi`.
 */

import type { HttpClient } from '../../api/http-client'
import type { ChatEvent } from './events'
import { readSse } from './sse-parser'

export type ChatRequest = {
  question: string
  /** Generated by the client (one per conversation). The backend keys memory by tenant + user + this id. */
  conversationId: string
}

export type ChatApi = {
  streamAnswer(request: ChatRequest, signal?: AbortSignal): AsyncIterable<ChatEvent>
}

export function createHttpChatApi(client: HttpClient, path = '/agent/stream'): ChatApi {
  return {
    async *streamAnswer(request, signal) {
      const body = { question: request.question, conversation_id: request.conversationId }
      yield* readSse(await client.stream(path, body, signal))
    },
  }
}
